static <K, V> ReferenceEntry<K, V> getReferenceEntry(Cache<K, V> cache, K key) {
  checkNotNull(cache);
  checkNotNull(key);
  LocalCache<K, V> map = toLocalCache(cache);
  return map.getEntry(key);
